import{_ as s,o as n,c as t,am as e}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"虚拟机 VirtualBox","description":"","frontmatter":{"title":"虚拟机 VirtualBox","excerpt":"VirtualBox 虚拟机安装","date":"2024-10-02 11:31:46","updated":"2024-10-02 11:31:46"},"headers":[],"relativePath":"部署&工具/虚拟机系统/虚拟机 VirtualBox.md","filePath":"部署&工具/虚拟机系统/虚拟机 VirtualBox.md","lastUpdated":null}'),l={name:"部署&工具/虚拟机系统/虚拟机 VirtualBox.md"};function p(i,a,r,o,c,h){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h2 id="下载地址" tabindex="-1">下载地址 <a class="header-anchor" href="#下载地址" aria-label="Permalink to &quot;下载地址&quot;">​</a></h2><p>VirtualBox官网地址如下： <a href="https://www.virtualbox.org/" target="_blank" rel="noreferrer">https://www.virtualbox.org/</a></p><p>镜像文件下载：</p><p>ubuntu官网地址如下： <a href="https://ubuntu.com/" target="_blank" rel="noreferrer">https://ubuntu.com/</a></p><p>windows官网地址如下： <a href="https://www.microsoft.com/zh-cn/" target="_blank" rel="noreferrer">https://www.microsoft.com/zh-cn/</a></p><p>阿里官网镜像地址如下： <a href="https://developer.aliyun.com/mirror/" target="_blank" rel="noreferrer">https://developer.aliyun.com/mirror/</a></p><hr><ul><li>参考链接： <a href="https://blog.csdn.net/GoodburghCottage/article/details/130307152" target="_blank" rel="noreferrer">https://blog.csdn.net/GoodburghCottage/article/details/130307152</a></li></ul><h2 id="安装到d盘显示无效目录" tabindex="-1">安装到D盘显示无效目录 <a class="header-anchor" href="#安装到d盘显示无效目录" aria-label="Permalink to &quot;安装到D盘显示无效目录&quot;">​</a></h2><p>参考： <a href="https://zhuanlan.zhihu.com/p/720970597" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/720970597</a></p><p>官方的文档说明： <a href="https://www.virtualbox.org/manual/topics/installation.html#install-win-installdir-req" target="_blank" rel="noreferrer">https://www.virtualbox.org/manual/topics/installation.html#install-win-installdir-req</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icacls &lt;Directory&gt; /reset /t /c</span></span>
<span class="line"><span>icacls &lt;Directory&gt; /inheritance:d /t /c</span></span>
<span class="line"><span>icacls &lt;Directory&gt; /grant *S-1-5-32-545:(OI)(CI)(RX)</span></span>
<span class="line"><span>icacls &lt;Directory&gt; /deny  *S-1-5-32-545:(DE,WD,AD,WEA,WA)</span></span>
<span class="line"><span>icacls &lt;Directory&gt; /grant *S-1-5-11:(OI)(CI)(RX)</span></span>
<span class="line"><span>icacls &lt;Directory&gt; /deny  *S-1-5-11:(DE,WD,AD,WEA,WA)</span></span></code></pre></div><p><code>&lt;Directory&gt; 替换为你的安装目录。例如：</code>D:\\VirtualBox\`\`</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icacls D:\\VirtualBox /reset /t /c</span></span>
<span class="line"><span>icacls D:\\VirtualBox /inheritance:d /t /c</span></span>
<span class="line"><span>icacls D:\\VirtualBox /grant *S-1-5-32-545:(OI)(CI)(RX)</span></span>
<span class="line"><span>icacls D:\\VirtualBox /deny  *S-1-5-32-545:(DE,WD,AD,WEA,WA)</span></span>
<span class="line"><span>icacls D:\\VirtualBox /grant *S-1-5-11:(OI)(CI)(RX)</span></span>
<span class="line"><span>icacls D:\\VirtualBox /deny  *S-1-5-11:(DE,WD,AD,WEA,WA)</span></span></code></pre></div><p>使用运行+ R 打开 cmd 窗口</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250330232948.png" alt="image.png"></p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ol><li>安装目录，选择根目录下的第一级目录，如果选择多级目录，每级目录都需要替换命令中的 <code>&lt;Directory&gt;</code>进行执行一次；</li><li>命令的执行，需要打开 cmd 命令提示符，不要使用 PowerShell。</li></ol><h2 id="主机无法访问虚拟机的网络" tabindex="-1">主机无法访问虚拟机的网络 <a class="header-anchor" href="#主机无法访问虚拟机的网络" aria-label="Permalink to &quot;主机无法访问虚拟机的网络&quot;">​</a></h2><p>虚拟机系统安装的是 centos7, 安装方式的 Gxxx 桌面</p><p>参考一下这篇： <a href="https://blog.51cto.com/u_16099219/13003639" target="_blank" rel="noreferrer">https://blog.51cto.com/u_16099219/13003639</a></p><p>管理 → 工具 → 网络管理器</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250331090506.png" alt="image.png"></p><p>跟上面没关系，忽略上面</p><p>虚拟机 → 设置 → 网络，然后进入到下面的界面</p><p>概念说明（后续建议先使用 deepseek 查询内容，不行再找百度&quot;低质内容更多“）：</p><ol><li><p>连接方式建议选择以下之一：</p><ul><li><p><strong>桥接网卡</strong>：虚拟机将获得与宿主机同网段的独立IP</p></li><li><p><strong>NAT</strong>：虚拟机通过宿主机的IP上网(默认)</p></li><li><p><strong>Host-Only</strong>：仅宿主机与虚拟机之间通信</p></li></ul></li></ol><p>网络管理器，自己这里选择开两个网卡（虚拟机关机的时候设置）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250331214811.png" alt="image.png"></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250331214824.png" alt="image.png"></p><p>这里自己是能默认访问的，地址选择 enp)s8 的这个地址</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250331214642.png" alt="image.png"></p><p>防火墙设置</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 查看防火墙状态</span></span>
<span class="line"><span>systemctl status firewalld</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 临时关闭防火墙（不推荐生产环境）</span></span>
<span class="line"><span>systemctl stop firewalld</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 或者添加允许的端口</span></span>
<span class="line"><span>firewall-cmd --permanent --add-port=80/tcp</span></span>
<span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><p>可选</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#禁止防火墙开机启动</span></span>
<span class="line"><span>systemctl disable firewalld</span></span></code></pre></div><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><p>退出窗口：alt + 右 ctrl</p><p>centos 显示IP地址的命令是</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig</span></span></code></pre></div><h3 id="网络连接模式" tabindex="-1">网络连接模式 <a class="header-anchor" href="#网络连接模式" aria-label="Permalink to &quot;网络连接模式&quot;">​</a></h3><ul><li><strong>桥接模式</strong>：虚拟机会像一台独立的真实主机一样，直接连接到你的物理网络。如果物理网络需要手动分配IP（如公司内网），或者有MAC地址绑定，虚拟机可能无法获取IP。 <ul><li><strong>检查</strong>：确保虚拟机IP地址段和宿主机在同一网段。如果宿主机是 <code>192.168.1.x</code>，虚拟机也应该是。</li></ul></li><li><strong>NAT模式</strong>：虚拟机通过宿主机“共享”一个IP地址上网。这是<strong>最不容易出错的默认模式</strong>，适合绝大多数上网场景。 <ul><li><strong>检查</strong>：如果你是单纯为了让虚拟机能上网，优先选择此模式。</li></ul></li><li><strong>仅主机模式</strong>：虚拟机只能与宿主机及其他使用“仅主机模式”的虚拟机通信，<strong>无法连接外网</strong>。 <ul><li><strong>检查</strong>：确认你的需求，如果是要访问互联网，不要选这个模式</li></ul></li></ul>`,42)])])}const g=s(l,[["render",p]]);export{u as __pageData,g as default};
